package net.minecraft.world.item;import net.minecraft.world.level.ItemLike;public class ItemStack{public final Item item;public int count;public String component="";public ItemStack(ItemLike i,int n){item=(Item)i;count=n;}public Item getItem(){return item;}public boolean isEmpty(){return count==0;}public ItemStack copy(){ItemStack s=new ItemStack(item,count);s.component=component;return s;}public static boolean isSameItemSameComponents(ItemStack a,ItemStack b){return a.item.equals(b.item)&&a.component.equals(b.component);}}
